// 연결 경계: UI는 이 저장소 인터페이스만 사용. 실제 API 어댑터로 교체 가능.
export const stages=['작업 중','검표 중','탑승 가능','충돌','배포 대기'];
const titles=['미디어 업로드 권한을 명확하게','작업 카드에 진행 상태 표시','기여 기록을 한눈에 연결','작업판 정렬 기준 개선','MCP 도구 설명 정리','알림 도착 경로 확인','모바일 세이브 상세 개선','문서 읽기 흐름 단순화','검표 결과 요약 개선'];
const initial=titles.map((credit,i)=>({id:`S-${1849-i}`,credit,task:{id:`T-${230+i}`,title:credit},actor:i%3===0?'paradigmdragon · 사람':i%3===1?'Claude · AI':'Codex · AI',status:stages[[4,2,1,3,4,0,2,0,1][i]],time:`${15-Math.floor(i/4)}:${String(52-i*5%50).padStart(2,'0')}`,tickets:[{path:i===3?'work_board.py':`src/${['MediaUpload','TaskCard','Credits','Board','Tools','Push','SaveDetail','Documents','Inspection'][i]}.tsx`,scope:i===3?'정렬 규칙':'화면 및 계약 범위'}],verification:{status:i===3?'충돌 발견':i===0||i===4||i===1||i===6?'통과':'미완료',evidence:i===3?'S-1850과 동일 정렬 함수 수정':'체험용 검증 결과 · 실제 실행 증거 아님'},contributors:[{name:'paradigmdragon',kind:'사람',role:'방향·요구조건'},{name:i%2?'Claude':'Codex',kind:'AI',role:'구현'},{name:'Sophia',kind:'AI',role:'로컬 검표'}],integration:{status:i===0||i===4?'통합 완료':'미통합',ref:i===0?'mock-commit-a17':'실제 GitHub 연결 전'},deployments:[],conflict:i===3?{reason:'두 세이브가 같은 작업판 정렬 함수를 서로 다른 기준으로 수정합니다.',impact:'작업판 표시 순서 · S-1846 / S-1850',proposal:'S-1850의 상태 기준을 먼저 반영한 뒤 S-1846의 시간 정렬을 재적용합니다.',resolved:false,orderAdjusted:false}:null}));
export class MockRepository{constructor(){this.reset()}reset(){this.saves=structuredClone(initial);this.events=[];this.branch={name:'새 작업맵',base:'본선 #76',overlay:['E-41','E-42'],hold:true};}list(){return this.saves}get(id){return this.saves.find(s=>s.id===id)}act(id,action){const s=this.get(id);if(!s)throw Error('세이브를 찾을 수 없습니다.');if(action==='hold')s.status='보류';if(action==='resume')s.status=s.conflict&&!s.conflict.resolved?'충돌':'탑승 가능';if(action==='order'){s.conflict.orderAdjusted=true;}if(action==='recheck'){if(s.conflict&&!s.conflict.resolved){if(s.status!=='보류')s.status='충돌';s.verification.status='충돌 발견';}else{s.status='탑승 가능';s.verification.status='통과';}}if(action==='board'){if(s.status!=='탑승 가능'||s.verification.status!=='통과'||s.conflict&&!s.conflict.resolved)throw Error('검표 통과한 세이브만 탑승할 수 있습니다.');s.status='배포 대기';}if(action==='unboard')s.status='탑승 가능';this.events.unshift({id,time:new Date().toLocaleTimeString('ko-KR',{timeZone:'Asia/Seoul'}),action});return s;}syncBranch(){return this.branch.hold?'동기화 보류: 탑승권 충돌이 남아 있습니다.':'최신 본선과 동기화했습니다.'}}
export const repository=new MockRepository();
